import {esc,stamp,chartHTML} from './charts.js';
const price=(v,c)=>Number.isFinite(v)?new Intl.NumberFormat('en-CA',{style:'currency',currency:c||'USD',maximumFractionDigits:4}).format(v):'—';
const badge=(text)=>`<span class="badge">${esc(text)}</span>`;
export function ibkrPanel(feed){
  if(!feed?.enabled){
    const state=feed?.status||'checking',ready=feed?.configured;
    const label=state==='setup-required'?'SETUP REQUIRED':state==='locked'?'PRIVATE FEED LOCKED':state==='checking'?'CHECKING CONNECTION':'CONNECTION UNAVAILABLE';
    return `<section class="panel"><div class="panel-head"><div><span class="eyebrow">IBKR CONNECTION</span><h2>Private market feed</h2></div>${badge(label)}</div><div class="details"><p>${esc(feed?.note||feed?.error||'Checking the hosted relay configuration.')}</p><p>Your Mac sends quote snapshots through an authenticated relay. The gateway must remain open; market-data subscriptions are separate.</p>${ready?`<form id="ibkr-unlock"><label for="ibkr-access-key">Private access key</label><div class="chart-toolbar"><input id="ibkr-access-key" type="password" name="token" autocomplete="off" required maxlength="128" placeholder="Enter your Northstar view key"><button class="button" type="submit">Unlock feed</button></div><p id="ibkr-auth-error" role="status"></p></form>`:'<p>The local pilot is available at <a href="http://127.0.0.1:4176/#markets">127.0.0.1:4176</a> on the Mac running Gateway. Hosting setup does not happen automatically when a PR is merged.</p>'}</div></section>`;
  }
  const connected=feed.connected;
  return `<section class="panel"><div class="panel-head"><div><span class="eyebrow">${feed.transport==='hosted'?'PRIVATE HOSTED PILOT':'PRIVATE LOCAL PILOT'}</span><h2>IBKR gateway</h2></div><div>${badge(connected?'API CONNECTED':feed.status||'OFFLINE')}${feed.transport==='hosted'?'<button id="ibkr-lock" class="button">Lock feed</button>':''}</div></div><div class="details"><p>${connected?'Gateway connected. Data access is checked separately for each contract.':(feed.note||'Quotes are disconnected. Start the connector and keep this Mac and gateway awake.')}</p><p>Read-only · No IBKR orders · ${feed.transport==='hosted'?'Relay uploads every 30 seconds · dashboard checks every 15 seconds':'Dashboard checks every 2 seconds'} · Receipt times, not exchange times</p></div><div class="table-scroll"><table><thead><tr><th>Instrument</th><th>Class</th><th>Feed type</th><th>Bid / ask status</th><th>Bid</th><th>Ask</th><th>Last reported</th></tr></thead><tbody>${(feed.assets||[]).map(a=>`<tr><td><b>${esc(a.symbol)}</b><small>${esc(a.currency)} · ${esc(a.exchange)}</small></td><td>${esc(a.category)}</td><td>${badge(a.mode)}</td><td>${badge(a.status)}</td><td>${price(a.bid,a.currency)}</td><td>${price(a.ask,a.currency)}</td><td>${price(a.last,a.currency)}<small>Received ${stamp(a.lastReceivedAt)}</small></td></tr>`).join('')||'<tr><td colspan="7">Waiting for contract discovery and quotes.</td></tr>'}</tbody></table></div><div class="panel-foot">Delayed, frozen, incomplete, and stale quotes cannot qualify as live. Derivatives execution is not enabled.</div>${(feed.assets?.some(a=>a.mode==='delayed'||a.mode==='delayed-frozen')||feed.events?.some(e=>[354,10167,10168,10089,10090,10091].includes(e.code)))?'<div class="unavailable-banner"><p>IBKR reports missing live-data entitlements. Delayed data may still appear below.</p></div>':''}</section>`;
}
export function ibkrMarket(feed,category,region,selected){
  if(!feed?.enabled)return null;
  const assets=feed.assets.filter(a=>a.category===category&&a.region===region);
  if(!assets.length)return null;
  const a=assets.find(a=>a.id===selected)||assets[0];
  const series=[{name:a.symbol,color:'#65ebc5',currency:a.currency,points:a.history||[]}];
  return {series,html:`<section class="panel"><div class="panel-head"><div><span class="eyebrow">IBKR · ${esc(category)} · ${esc(region)}</span><h2>${esc(a.symbol)}</h2></div>${badge(a.mode+' · '+a.status)}</div><div class="chart-toolbar">${assets.map(q=>`<button class="button" data-ibkr-asset="${esc(q.id)}" aria-pressed="${q.id===a.id}">${esc(q.symbol)}</button>`).join('')}<span class="dim">${esc(a.currency)} · Bid / ask midpoint · Observed this session</span></div>${chartHTML(series,{label:`${a.symbol} recorded ${a.mode} bid / ask midpoint in ${a.currency}`})}<div class="quote-grid"><article class="stat"><span class="label">Bid</span><strong>${price(a.bid,a.currency)}</strong><small>Received ${stamp(a.bidReceivedAt)}</small></article><article class="stat"><span class="label">Ask</span><strong>${price(a.ask,a.currency)}</strong><small>Received ${stamp(a.askReceivedAt)}</small></article><article class="stat"><span class="label">Last reported trade</span><strong>${price(a.last,a.currency)}</strong><small>May be an earlier session trade · ${esc(a.mode)}</small></article></div><div class="details"><p>Contract ${esc(a.conId)} · ${esc(a.exchange)}${a.expiry?' · Expiry '+esc(a.expiry):''}${a.multiplier?' · Multiplier '+esc(a.multiplier):''}${a.right?' · '+esc(a.right)+' · Strike '+esc(a.strike):''}</p>${a.error?`<p>${esc(a.error)}</p>`:''}<p>Chart begins when the connector starts. Gaps mean no valid two-sided quote. Prices are in ${esc(a.currency)}; contract prices are not the total cost or margin requirement.</p></div><div class="panel-foot">Market observation only. The crypto strategy does not trade this instrument.</div></section>`};
}
